export const BEHAVIORAL_SOCIAL_BASICS_B_QUIZZES = [
  {
    id:`ps139`, cat:`Behavioral & Social Sciences`, title:`The Civil Rights Movement: Key Figures & Events`, diff:`Medium`,
    qs:[
      { q:`In Brown v. Board of Education (1954), the Supreme Court ruled that:`, ch:[`Racial segregation in public schools is inherently unequal and violates the Constitution`,`"Separate but equal" facilities are constitutional if truly equal`,`States may decide segregation policy without federal interference`,`Public school funding must be identical across all districts`], ans:0, exp:`In Brown v. Board of Education, the Supreme Court unanimously ruled that racially segregated public schools violate the Equal Protection Clause of the 14th Amendment, overturning the "separate but equal" doctrine from Plessy v. Ferguson.` },
      { q:`Rosa Parks's refusal to give up her bus seat in 1955 sparked the:`, ch:[`March on Washington`,`Montgomery Bus Boycott`,`Selma to Montgomery marches`,`Freedom Rides`], ans:1, exp:`Rosa Parks's arrest for refusing to give up her seat to a white passenger in Montgomery, Alabama, led to a 381-day boycott of the city's buses, organized in part by a young Martin Luther King Jr.` },
      { q:`Martin Luther King Jr. delivered his famous "I Have a Dream" speech during the:`, ch:[`Selma to Montgomery march`,`Birmingham campaign`,`March on Washington for Jobs and Freedom`,`Poor People's Campaign`], ans:2, exp:`King delivered the speech on August 28, 1963, at the March on Washington, a massive rally at the Lincoln Memorial that helped build momentum for civil rights legislation.` },
      { q:`The Civil Rights Act of 1964 primarily:`, ch:[`Guaranteed voting rights nationwide`,`Ended segregation in the U.S. military`,`Established federal affirmative action quotas`,`Outlawed discrimination based on race, color, religion, sex, or national origin in employment and public accommodations`], ans:3, exp:`The Civil Rights Act of 1964 banned discrimination in public accommodations, employment, and federally funded programs; voting protections came a year later with the Voting Rights Act of 1965.` },
      { q:`The Voting Rights Act of 1965 was passed largely in response to violence during the:`, ch:[`Selma to Montgomery marches, including "Bloody Sunday"`,`Little Rock Nine crisis`,`March on Washington`,`Birmingham church bombing`], ans:0, exp:`Televised images of police violence against marchers on "Bloody Sunday" in Selma helped build public and congressional support for the Voting Rights Act, which banned discriminatory voting practices like literacy tests.` },
      { q:`The "Little Rock Nine" refers to:`, ch:[`Nine Freedom Riders arrested in Alabama`,`Nine Black students who integrated Central High School in Little Rock in 1957`,`Nine organizers of the March on Washington`,`Nine plaintiffs consolidated in Brown v. Board of Education`], ans:1, exp:`In 1957, nine Black students enrolled at Little Rock Central High School under federal protection after Arkansas's governor tried to block integration, becoming a major test of Brown v. Board's enforcement.` },
      { q:`Unlike Martin Luther King Jr.'s strategy of nonviolent civil disobedience, Malcolm X (in his early public career) argued that African Americans should:`, ch:[`Rely solely on nonviolent civil disobedience`,`Pursue change only through electoral politics`,`Defend themselves and pursue rights "by any means necessary"`,`Focus exclusively on interracial coalition-building`], ans:2, exp:`Malcolm X, associated with the Nation of Islam for much of his early career, promoted Black self-determination and self-defense, contrasting with King's philosophy of nonviolent resistance.` },
      { q:`The Freedom Rides of 1961 were organized to:`, ch:[`Register Black voters across the Deep South`,`Protest employment discrimination in Northern factories`,`Demand the integration of public universities`,`Test compliance with rulings that banned segregation on interstate buses and in terminals`], ans:3, exp:`Freedom Riders rode interstate buses into the segregated South to test enforcement of Supreme Court rulings that banned segregation in interstate bus travel and terminals, often facing violent resistance.` },
      { q:`"Bloody Sunday" (March 7, 1965) refers to the day when:`, ch:[`Police attacked peaceful voting-rights marchers crossing the Edmund Pettus Bridge in Selma`,`The March on Washington turned violent`,`The 16th Street Baptist Church was bombed`,`The Little Rock Nine were blocked from entering school`], ans:0, exp:`On Bloody Sunday, state troopers violently attacked peaceful voting-rights marchers as they attempted to cross the Edmund Pettus Bridge in Selma, Alabama, shocking the nation.` },
      { q:`Which organization did Martin Luther King Jr. help found and lead to coordinate nonviolent civil rights protests?`, ch:[`NAACP`,`Southern Christian Leadership Conference (SCLC)`,`Congress of Racial Equality (CORE)`,`Student Nonviolent Coordinating Committee (SNCC)`], ans:1, exp:`King co-founded the SCLC in 1957 to harness the moral authority of Black churches and coordinate nonviolent direct action campaigns across the South.` },
      { q:`The Plessy v. Ferguson (1896) decision, later overturned by Brown v. Board of Education, established the legal doctrine of:`, ch:[`"Clear and present danger"`,`"One person, one vote"`,`"Separate but equal"`,`"Equal protection under all circumstances"`], ans:2, exp:`Plessy v. Ferguson upheld racial segregation under the doctrine of "separate but equal," a precedent that stood for nearly 60 years until Brown v. Board declared segregated schools inherently unequal.` }
    ]
  },
  {
    id:`ps140`, cat:`Behavioral & Social Sciences`, title:`Women's Suffrage & the Fight for Equal Rights`, diff:`Easy`,
    qs:[
      { q:`The 1848 Seneca Falls Convention, considered the launch of the organized women's rights movement in the U.S., produced a document called the:`, ch:[`Emancipation Proclamation`,`Declaration of Sentiments`,`Bill of Rights`,`Nineteenth Amendment`], ans:1, exp:`Modeled on the Declaration of Independence, the Declaration of Sentiments, drafted largely by Elizabeth Cady Stanton, demanded social and political equality for women, including the right to vote.` },
      { q:`The right of women to vote nationwide in the United States was formally guaranteed by:`, ch:[`The Fourteenth Amendment (1868)`,`The Seneca Falls Declaration (1848)`,`The Nineteenth Amendment (1920)`,`The Civil Rights Act (1964)`], ans:2, exp:`Ratified in 1920, the Nineteenth Amendment prohibits denying citizens the right to vote on the basis of sex, capping decades of activism by suffragists.` },
      { q:`Suffragist Susan B. Anthony became famous for:`, ch:[`Serving as the first female U.S. senator`,`Writing the Declaration of Independence`,`Founding the first women's college`,`Being arrested and fined for illegally voting in the 1872 presidential election`], ans:3, exp:`Anthony voted in the 1872 election to challenge restrictions on women's suffrage; she was arrested, tried, and fined, though she refused to pay, drawing national attention to the cause.` },
      { q:`The National American Woman Suffrage Association (NAWSA) was formed in 1890 by merging two rival suffrage organizations, one led by Elizabeth Cady Stanton and Susan B. Anthony and the other by:`, ch:[`Lucy Stone`,`Sojourner Truth`,`Alice Paul`,`Frances Willard`], ans:0, exp:`NAWSA merged the National Woman Suffrage Association (Stanton/Anthony) with the American Woman Suffrage Association, led by Lucy Stone, unifying the movement's strategy.` },
      { q:`Alice Paul and the National Woman's Party used more confrontational tactics than earlier suffragists, including:`, ch:[`Organizing armed militias`,`Picketing the White House and enduring hunger strikes in prison`,`Boycotting all elections`,`Refusing to pay any federal taxes`], ans:1, exp:`Alice Paul organized silent pickets outside the White House starting in 1917; many picketers were arrested and some, including Paul, went on hunger strikes while imprisoned, drawing public sympathy.` },
      { q:`Sojourner Truth, a formerly enslaved woman, is best known for a speech connecting the fights for abolition and women's rights, commonly titled:`, ch:[`"Free at Last"`,`"The Fire Next Time"`,`"Ain't I a Woman?"`,`"I Have a Dream"`], ans:2, exp:`Delivered in 1851, Sojourner Truth's speech challenged the exclusion of Black women from dominant narratives of both womanhood and suffrage, linking racial and gender equality.` },
      { q:`The Equal Pay Act of 1963 was designed to:`, ch:[`Guarantee women the right to serve on juries`,`Require companies to hire equal numbers of men and women`,`Establish paid maternity leave nationwide`,`Prohibit wage discrimination based on sex for equal work`], ans:3, exp:`The Equal Pay Act amended the Fair Labor Standards Act to require that men and women receive equal pay for substantially equal work performed under similar conditions.` },
      { q:`Title IX, passed in 1972, is best known for its impact on:`, ch:[`Expanding opportunities for women in federally funded education and athletics`,`Granting women the right to vote`,`Legalizing birth control nationwide`,`Establishing the first female cabinet position`], ans:0, exp:`Title IX bans sex discrimination in any education program receiving federal funding, dramatically expanding girls' and women's access to school athletics and academic programs.` },
      { q:`The Equal Rights Amendment (ERA), which would explicitly guarantee equal legal rights for all citizens regardless of sex, was:`, ch:[`Ratified in 1920 alongside the Nineteenth Amendment`,`Passed by Congress in 1972 but has not been added to the Constitution through the standard ratification process by enough states within its original deadlines`,`Rejected by Congress and never sent to the states`,`Immediately ratified by all fifty states in 1972`], ans:1, exp:`Congress passed the ERA in 1972 and sent it to the states, but it fell short of ratification by the required three-fourths of states before its extended deadline, leaving its constitutional status contested.` },
      { q:`Historians commonly describe the suffrage movement (roughly 1848-1920) as "first-wave feminism," while the women's movement of the 1960s-1980s, which focused on issues like workplace equality and reproductive rights, is called:`, ch:[`Third-wave feminism`,`Postmodern feminism`,`Second-wave feminism`,`Radical feminism`], ans:2, exp:`"Second-wave feminism" refers to the resurgence of activism from the 1960s through the 1980s, broadening the focus from voting rights to workplace discrimination, reproductive rights, and family law.` },
      { q:`Which U.S. territory was the first to grant women full voting rights, in 1869, more than 50 years before the Nineteenth Amendment?`, ch:[`California`,`New York`,`Massachusetts`,`Wyoming`], ans:3, exp:`Wyoming Territory granted women full voting rights in 1869, and when it became a state in 1890, it retained the distinction of being the first state with women's suffrage.` }
    ]
  },
  {
    id:`ps141`, cat:`Behavioral & Social Sciences`, title:`The Cold War & the Space Race`, diff:`Medium`,
    qs:[
      { q:`The "Cold War" refers to the post-World War II era of geopolitical tension primarily between:`, ch:[`Britain and France`,`Germany and the Soviet Union`,`The United States and the Soviet Union`,`China and Japan`], ans:2, exp:`The Cold War (roughly 1947-1991) was a prolonged period of political, economic, and military rivalry between the U.S.-led Western bloc and the Soviet-led Eastern bloc, marked by proxy conflicts rather than direct war between the superpowers.` },
      { q:`The term "Iron Curtain," used to describe the ideological and physical divide between Western Europe and Soviet-controlled Eastern Europe, was popularized by:`, ch:[`Franklin D. Roosevelt`,`Joseph Stalin`,`Harry Truman`,`Winston Churchill`], ans:3, exp:`Winston Churchill used the phrase "Iron Curtain" in a 1946 speech to describe the division separating democratic Western Europe from communist Eastern Europe.` },
      { q:`The Space Race is often said to have begun in 1957 when the Soviet Union launched:`, ch:[`Sputnik, the first artificial satellite to orbit Earth`,`Apollo 11, the first crewed Moon landing`,`Vostok 1, the first crewed orbital spaceflight`,`Voyager 1, the first probe to leave the solar system`], ans:0, exp:`The Soviet Union's launch of Sputnik in October 1957 was the first artificial satellite in orbit, shocking the U.S. and triggering an intense space race between the two superpowers.` },
      { q:`The first human to travel into space and orbit the Earth, in 1961, was:`, ch:[`Neil Armstrong`,`Yuri Gagarin`,`John Glenn`,`Alan Shepard`], ans:1, exp:`Soviet cosmonaut Yuri Gagarin became the first human in space and the first to orbit Earth aboard Vostok 1 in April 1961.` },
      { q:`The United States won a key milestone of the Space Race in July 1969 when:`, ch:[`It launched the first artificial satellite`,`It sent the first human into orbit`,`Apollo 11 astronauts Neil Armstrong and Buzz Aldrin became the first humans to walk on the Moon`,`It launched the first space station`], ans:2, exp:`Apollo 11's Moon landing on July 20, 1969, fulfilled President Kennedy's 1961 goal of landing Americans on the Moon before the decade's end, a major symbolic Cold War victory for the U.S.` },
      { q:`The 1962 Cuban Missile Crisis, often considered the closest the Cold War came to nuclear war, was triggered by:`, ch:[`The construction of the Berlin Wall`,`The launch of Sputnik`,`A Soviet invasion of West Germany`,`The discovery of Soviet nuclear missiles being placed in Cuba`], ans:3, exp:`The crisis began when U.S. reconnaissance discovered Soviet nuclear missiles in Cuba, just 90 miles from Florida; a tense standoff ended with a Soviet withdrawal in exchange for a secret U.S. pledge to remove missiles from Turkey.` },
      { q:`The Berlin Wall, built in 1961 to stop East Germans from fleeing to the West, became one of the most famous symbols of the Cold War until it:`, ch:[`Fell in 1989, symbolizing the collapse of Soviet control over Eastern Europe`,`Was destroyed during World War II`,`Was replaced by a fence in the 1970s`,`Remains standing today as a museum`], ans:0, exp:`The fall of the Berlin Wall in November 1989 symbolized the crumbling of Soviet influence in Eastern Europe and preceded German reunification and the eventual end of the Cold War.` },
      { q:`During the Cold War, the United States and its Western allies formed the military alliance NATO, while the Soviet Union and its Eastern European allies formed a rival alliance called the:`, ch:[`United Nations`,`Warsaw Pact`,`League of Nations`,`Non-Aligned Movement`], ans:1, exp:`The Warsaw Pact (1955) was a mutual defense treaty among the Soviet Union and its Eastern European satellite states, formed partly in response to NATO's creation in 1949.` },
      { q:`The U.S. Cold War strategy known as "containment" was aimed primarily at:`, ch:[`Expanding U.S. territory in Europe`,`Merging the U.S. and Soviet economies`,`Preventing the spread of communism to new countries`,`Ending all foreign aid programs`], ans:2, exp:`Containment, articulated in the Truman Doctrine (1947), guided U.S. foreign policy to stop the spread of Soviet communism through economic aid, alliances, and, at times, military intervention.` },
      { q:`The Cold War concept of "Mutual Assured Destruction" (MAD) referred to the idea that:`, ch:[`Only one superpower possessed nuclear weapons`,`Nuclear weapons were banned by international treaty`,`Space exploration would prevent nuclear war`,`A full-scale nuclear attack by either superpower would result in the destruction of both, deterring either side from striking first`], ans:3, exp:`MAD held that since both the U.S. and USSR had enough nuclear weapons to annihilate each other in a retaliatory strike, neither side had a rational incentive to launch a first strike.` },
      { q:`The Cold War is generally considered to have ended around:`, ch:[`1991, with the dissolution of the Soviet Union`,`1969, with the Apollo 11 Moon landing`,`1962, after the Cuban Missile Crisis`,`1945, at the end of World War II`], ans:0, exp:`The Cold War effectively ended with the collapse of the Soviet Union in December 1991, following years of political and economic reform and the loss of Soviet control over Eastern Europe.` }
    ]
  },
  {
    id:`ps142`, cat:`Behavioral & Social Sciences`, title:`The Progressive Era: Reformers & Reforms`, diff:`Medium`,
    qs:[
      { q:`The Progressive Era (roughly the 1890s to the 1920s) was primarily a response to social and political problems caused by:`, ch:[`The Great Depression`,`World War I`,`The Cold War`,`Rapid industrialization and urbanization`], ans:3, exp:`Progressive reformers responded to problems that emerged from rapid industrial growth and urban expansion in the late 1800s, including poor working conditions, political corruption, and public health hazards.` },
      { q:`Investigative journalists who exposed corruption, unsafe working conditions, and corporate abuses during the Progressive Era were known as:`, ch:[`Muckrakers`,`Carpetbaggers`,`Abolitionists`,`Federalists`], ans:0, exp:`Muckrakers like Upton Sinclair and Ida Tarbell wrote exposes on issues such as unsafe food production and monopolistic business practices, helping spur reform legislation.` },
      { q:`Upton Sinclair's novel "The Jungle," which exposed unsanitary conditions in the meatpacking industry, helped lead directly to the passage of the:`, ch:[`Sherman Antitrust Act`,`Pure Food and Drug Act`,`Social Security Act`,`Sixteenth Amendment`], ans:1, exp:`Public outrage over "The Jungle" prompted Congress to pass the Pure Food and Drug Act of 1906, establishing federal oversight of food and drug safety.` },
      { q:`The Seventeenth Amendment (1913), a key Progressive Era reform, established:`, ch:[`Women's right to vote`,`An income tax`,`The direct election of U.S. senators by popular vote instead of state legislatures`,`Prohibition of alcohol`], ans:2, exp:`Before the Seventeenth Amendment, U.S. senators were chosen by state legislatures; the amendment shifted their election to a direct popular vote, aiming to reduce corruption and increase accountability.` },
      { q:`The Sixteenth Amendment (1913) gave Congress the power to:`, ch:[`Regulate interstate railroads`,`Prohibit child labor nationwide`,`Break up monopolies`,`Levy a federal income tax`], ans:3, exp:`The Sixteenth Amendment authorized Congress to collect an income tax without apportioning it among the states based on population, creating a major new federal revenue source.` },
      { q:`President Theodore Roosevelt earned a reputation as a "trust-buster" for his efforts to:`, ch:[`Use antitrust laws to break up large monopolistic corporations`,`Nationalize the railroad industry`,`Abolish the income tax`,`End all labor unions`], ans:0, exp:`Roosevelt used the Sherman Antitrust Act to pursue lawsuits against major monopolies, such as Standard Oil, aiming to restore competition and curb corporate power.` },
      { q:`The Eighteenth Amendment (1919), a Progressive Era reform later repealed, established:`, ch:[`Women's suffrage`,`The nationwide prohibition of the manufacture and sale of alcohol`,`Child labor restrictions`,`Federal minimum wage laws`], ans:1, exp:`The Eighteenth Amendment banned the manufacture, sale, and transportation of alcoholic beverages in the U.S.; it proved difficult to enforce and was repealed by the Twenty-First Amendment in 1933.` },
      { q:`Jane Addams is best known for founding Hull House in Chicago, a pioneering example of the:`, ch:[`Labor union movement`,`Temperance movement`,`Settlement house movement, providing services to poor immigrant communities`,`Suffrage movement`], ans:2, exp:`Jane Addams's Hull House offered education, childcare, and social services to immigrant and working-class families, becoming a model for the broader settlement house movement.` },
      { q:`Progressive reformers introduced tools like the initiative, referendum, and recall primarily to:`, ch:[`Strengthen the power of political party bosses`,`Reduce voter participation in elections`,`Centralize decision-making in the federal executive branch`,`Give ordinary citizens more direct control over lawmaking and elected officials`], ans:3, exp:`The initiative, referendum, and recall were direct democracy tools that let citizens propose laws, vote directly on legislation, and remove officials from office, reducing the influence of political machines.` },
      { q:`A major goal of many Progressive Era reformers regarding children was to:`, ch:[`Restrict or eliminate child labor in factories and mines`,`Expand child labor to boost industrial output`,`Eliminate public schooling requirements`,`Lower the age at which children could vote`], ans:0, exp:`Progressives pushed for laws limiting the hours and conditions under which children could work, reflecting growing concern over child welfare and education, though national child labor laws faced early legal challenges.` },
      { q:`Which of the following presidents is most closely associated with advancing Progressive Era reforms while in office?`, ch:[`Andrew Jackson`,`Theodore Roosevelt`,`Ulysses S. Grant`,`Franklin Pierce`], ans:1, exp:`Theodore Roosevelt championed Progressive causes such as trust-busting, conservation, and consumer protection, embodying the reform spirit of the era during his presidency (1901-1909).` }
    ]
  },
  {
    id:`ps143`, cat:`Behavioral & Social Sciences`, title:`Immigration in American History`, diff:`Medium`,
    qs:[
      { q:`From 1892 to 1954, Ellis Island in New York Harbor served as the main entry point for:`, ch:[`Millions of immigrants arriving in the United States, primarily from Europe`,`Enslaved Africans brought to the colonies`,`Refugees fleeing the Civil War`,`American soldiers returning from war`], ans:0, exp:`Ellis Island processed roughly 12 million immigrants, most from Europe, making it the busiest U.S. immigration inspection station of its era.` },
      { q:`The Chinese Exclusion Act of 1882 was significant because it was:`, ch:[`The first federal law to grant citizenship to immigrants`,`The first major U.S. law to restrict immigration based on nationality`,`A law encouraging Chinese immigration for railroad labor`,`A treaty establishing open borders with China`], ans:1, exp:`The Chinese Exclusion Act barred nearly all immigration from China and was the first major federal law to restrict immigration explicitly based on a specific nationality; it remained in effect until 1943.` },
      { q:`Angel Island, located in San Francisco Bay, served a role similar to Ellis Island but primarily processed immigrants from:`, ch:[`Central America`,`Eastern Europe`,`Asia`,`West Africa`], ans:2, exp:`Angel Island Immigration Station (1910-1940) processed mostly Asian immigrants arriving on the West Coast, who often faced longer detentions and more intense scrutiny than European immigrants at Ellis Island.` },
      { q:`The Immigration Act of 1924 established a quota system that:`, ch:[`Eliminated all restrictions on immigration`,`Applied equally to every country in the world`,`Encouraged immigration from Asia and Africa`,`Sharply limited immigration overall and favored immigrants from Northern and Western Europe over other regions`], ans:3, exp:`The 1924 Act set national-origin quotas based on the 1890 census, heavily favoring Northern and Western European immigrants while severely restricting immigration from Southern/Eastern Europe, Asia, and elsewhere.` },
      { q:`The Immigration and Nationality Act of 1965 marked a major shift in U.S. immigration policy by:`, ch:[`Abolishing the national-origins quota system and opening immigration more broadly to people from all countries`,`Establishing the first quota system`,`Ending all legal immigration`,`Requiring English literacy tests for all immigrants`], ans:0, exp:`The 1965 Act eliminated the discriminatory national-origins quotas of 1924, instead prioritizing family reunification and skills, which significantly diversified the origins of U.S. immigrants in subsequent decades.` },
      { q:`The metaphor of a "melting pot" is often used to describe the idea that immigrants to the U.S.:`, ch:[`Should be denied citizenship`,`Blend together into a shared, unified American culture`,`Must return to their countries of origin after a set period`,`Should be geographically segregated by nationality`], ans:1, exp:`The "melting pot" metaphor suggests immigrants from different backgrounds assimilate and blend into a single unified culture, contrasting with the "salad bowl" metaphor, which emphasizes distinct cultures coexisting side by side.` },
      { q:`In the study of migration, "push factors" refer to conditions that:`, ch:[`Attract migrants to a new destination`,`Are unrelated to a person's decision to migrate`,`Drive people to leave their home country, such as war, famine, or persecution`,`Determine which port of entry migrants must use`], ans:2, exp:`Push factors (e.g., poverty, conflict, persecution) drive people to leave their home country, while pull factors (e.g., jobs, freedom, family) attract them to a new destination.` },
      { q:`The "Great Migration" refers to the movement, mainly between 1916 and 1970, of:`, ch:[`European immigrants moving from cities to farms`,`Native American tribes relocating westward`,`Irish immigrants arriving during the potato famine`,`Millions of African Americans moving from the rural South to cities in the North and West`], ans:3, exp:`The Great Migration saw roughly six million African Americans relocate from the rural South to industrial cities in the North, Midwest, and West, seeking better economic opportunities and to escape segregation.` },
      { q:`A major wave of Irish immigration to the United States in the 1840s was driven largely by:`, ch:[`The Great Famine (Potato Famine) in Ireland`,`Religious freedom laws in the U.S.`,`The Chinese Exclusion Act`,`The California Gold Rush`], ans:0, exp:`The Great Famine of the 1840s, caused by potato crop failure, led to mass starvation and emigration, with over a million Irish immigrants arriving in the U.S. during and after the crisis.` },
      { q:`The legal process by which a foreign-born person becomes a citizen of a country is called:`, ch:[`Deportation`,`Naturalization`,`Repatriation`,`Emigration`], ans:1, exp:`Naturalization is the process through which an immigrant lawfully acquires citizenship in a new country, typically after meeting residency and other legal requirements.` },
      { q:`The Deferred Action for Childhood Arrivals (DACA) program, established in 2012, provides certain young undocumented immigrants who arrived in the U.S. as children with:`, ch:[`Automatic U.S. citizenship`,`Permanent legal residency identical to a green card`,`Temporary protection from deportation and eligibility for work permits`,`Guaranteed college scholarships`], ans:2, exp:`DACA allows eligible individuals who came to the U.S. as children to receive renewable, temporary relief from deportation and apply for work authorization, though it does not grant permanent legal status or citizenship.` }
    ]
  },
  {
    id:`ps144`, cat:`Behavioral & Social Sciences`, title:`Latin American History Basics`, diff:`Easy`,
    qs:[
      { q:`European colonization of most of Latin America began in the late 15th and 16th centuries, led primarily by which two countries?`, ch:[`France and Britain`,`Spain and Portugal`,`Netherlands and Germany`,`Italy and Russia`], ans:1, exp:`Following Columbus's 1492 voyage, Spain colonized most of Latin America while Portugal colonized Brazil, establishing centuries of colonial rule that shaped the region's languages, religion, and institutions.` },
      { q:`Simon Bolivar is best known for:`, ch:[`Founding the Aztec Empire`,`Leading Brazil's independence from Portugal`,`Leading independence movements that liberated much of northern South America from Spanish rule`,`Serving as the first president of Mexico`], ans:2, exp:`Simon Bolivar led revolutionary campaigns in the early 1800s that helped win independence for present-day Venezuela, Colombia, Ecuador, Panama, Bolivia, and Peru, earning him the title "The Liberator."` },
      { q:`Unlike most of Spanish-speaking Latin America, Brazil achieved independence in 1822:`, ch:[`Through a violent decades-long revolution`,`With direct military support from Spain`,`By remaining a Portuguese colony indefinitely`,`Relatively peacefully, when Pedro I, son of the Portuguese king, declared Brazil independent and became its emperor`], ans:3, exp:`Brazil's path to independence differed from Spanish America's; it became an independent empire under Pedro I in 1822 without the prolonged warfare seen elsewhere in the region.` },
      { q:`The Aztec Empire, conquered by Spanish forces under Hernan Cortes in the early 1500s, was centered around its capital city of:`, ch:[`Tenochtitlan (in present-day Mexico)`,`Cusco (in present-day Peru)`,`Bogota (in present-day Colombia)`,`Havana (in present-day Cuba)`], ans:0, exp:`Tenochtitlan, built on an island in Lake Texcoco, was the Aztec capital and one of the largest cities in the world at the time; the site is now Mexico City.` },
      { q:`The Inca Empire, one of the largest empires in pre-Columbian America, was centered in the Andes Mountains with its capital at:`, ch:[`Tenochtitlan`,`Cusco`,`Havana`,`Rio de Janeiro`], ans:1, exp:`Cusco, in present-day Peru, served as the capital of the Inca Empire, which was conquered by Spanish conquistador Francisco Pizarro in the 1530s.` },
      { q:`The Mexican Revolution, beginning in 1910, was fought largely over issues including:`, ch:[`Independence from Portugal`,`Territorial disputes with Canada`,`Land reform, political dictatorship, and social inequality`,`Adoption of a new national language`], ans:2, exp:`The Mexican Revolution was a prolonged and violent conflict aimed at ending the long dictatorship of Porfirio Diaz and addressing deep inequalities in land ownership and political power.` },
      { q:`The Cuban Revolution of 1959, led by Fidel Castro, resulted in:`, ch:[`The restoration of Spanish colonial rule`,`Cuba joining NATO`,`A peaceful transition to a constitutional monarchy`,`The overthrow of dictator Fulgencio Batista and the establishment of a one-party communist government`], ans:3, exp:`Fidel Castro's guerrilla movement overthrew the U.S.-backed Batista government in 1959, eventually establishing a socialist state closely aligned with the Soviet Union during the Cold War.` },
      { q:`The Panama Canal, completed in 1914 and built with major U.S. involvement, is significant because it:`, ch:[`Created a shortcut for ships traveling between the Atlantic and Pacific Oceans`,`Separated North and South America for the first time`,`Was the first canal built in Latin America by Spain`,`Connected Mexico City to the Pacific coast`], ans:0, exp:`The Panama Canal allows ships to pass between the Atlantic and Pacific Oceans without sailing around South America, dramatically shortening travel times and boosting global trade.` },
      { q:`The Amazon Rainforest, the largest tropical rainforest in the world, is located mostly within the borders of:`, ch:[`Argentina`,`Brazil`,`Mexico`,`Chile`], ans:1, exp:`The Amazon Rainforest spans several South American countries but lies mostly within Brazil, which contains roughly 60% of the forest.` },
      { q:`Simon Bolivar's vision of a unified South American state called "Gran Colombia" ultimately:`, ch:[`Became the permanent government of all South America`,`Was never attempted`,`Broke apart into separate independent nations, including present-day Colombia, Venezuela, and Ecuador`,`Merged with the United States`], ans:2, exp:`Gran Colombia, formed after independence, dissolved by 1831 due to regional political tensions, splitting into the separate nations of Venezuela, Colombia (then including Panama), and Ecuador.` },
      { q:`Mercosur, a regional trade bloc formed in 1991 by countries including Argentina, Brazil, Paraguay, and Uruguay, was created mainly to:`, ch:[`Establish a single Latin American currency`,`Coordinate military defense against outside invasion`,`Merge the member countries into one nation`,`Promote free trade and economic integration among member countries`], ans:3, exp:`Mercosur (Southern Common Market) is a trade bloc designed to reduce trade barriers and promote economic cooperation among its South American member states.` }
    ]
  },
  {
    id:`ps145`, cat:`Behavioral & Social Sciences`, title:`African History Basics: Empires & Colonization`, diff:`Easy`,
    qs:[
      { q:`Mansa Musa, widely regarded as one of the wealthiest individuals in history, ruled which West African empire in the 14th century?`, ch:[`Songhai Empire`,`Kingdom of Kush`,`Mali Empire`,`Zulu Kingdom`], ans:2, exp:`Mansa Musa ruled the Mali Empire and became famous for his extraordinary wealth, largely from gold and salt trade, and for a lavish pilgrimage to Mecca in 1324 that spread his empire's fame across Africa and the Middle East.` },
      { q:`The impressive stone ruins of Great Zimbabwe, built between roughly the 11th and 15th centuries, served as:`, ch:[`A Roman military outpost`,`An Egyptian pyramid complex`,`A Portuguese colonial fort`,`The capital of a wealthy trading kingdom in southern Africa`], ans:3, exp:`Great Zimbabwe was the capital of a powerful African kingdom that grew wealthy through trade in gold and other goods, and its massive stone structures demonstrate advanced architectural and engineering skill.` },
      { q:`Trans-Saharan trade routes across the Sahara Desert connected West African kingdoms to North Africa and the Mediterranean, with two key traded goods being:`, ch:[`Gold and salt`,`Oil and coal`,`Rice and tea`,`Silk and porcelain`], ans:0, exp:`For centuries, camel caravans carried gold from West Africa north across the Sahara in exchange for salt (essential for food preservation) and other goods, fueling the wealth of empires like Ghana and Mali.` },
      { q:`The Berlin Conference of 1884-1885 is significant in African history because it:`, ch:[`Ended the transatlantic slave trade`,`Formalized European powers' division of Africa into colonial territories, largely without African representation`,`Granted independence to most African colonies`,`Established the African Union`], ans:1, exp:`At the Berlin Conference, European powers negotiated rules for colonizing Africa and drew borders for their claims with no African representation at the table, setting the stage for decades of colonial rule.` },
      { q:`The transatlantic slave trade, which lasted from roughly the 16th to the 19th centuries, forcibly transported millions of Africans primarily to:`, ch:[`Europe as domestic servants only`,`Asia for agricultural labor`,`The Americas to work on plantations and in mines`,`Australia for penal colonies`], ans:2, exp:`European traders forcibly transported an estimated 12 million or more enslaved Africans across the Atlantic to the Americas, where they were forced to labor primarily on plantations, a system that caused immense suffering and had lasting historical impacts.` },
      { q:`The ancient Kingdom of Kush, which at times conquered and ruled Egypt, was located along the Nile River in the region of present-day:`, ch:[`Morocco`,`Nigeria`,`South Africa`,`Sudan`], ans:3, exp:`Kush was an ancient African civilization centered in present-day Sudan, south of Egypt; it developed its own pyramids, writing system, and at one point ruled Egypt as the 25th Dynasty.` },
      { q:`The majority of African nations gained independence from European colonial rule primarily during which period?`, ch:[`The 1950s and 1960s`,`The 1800s`,`The 1990s`,`Immediately after World War I`], ans:0, exp:`A wave of decolonization swept across Africa in the 1950s and 1960s, as nations like Ghana (1957), Nigeria (1960), and many others achieved independence from European colonial powers.` },
      { q:`Apartheid was a system of institutionalized racial segregation and discrimination enforced in:`, ch:[`Egypt, from the 1800s to 1900s`,`South Africa, from 1948 until the early 1990s`,`Kenya, following independence`,`Nigeria, during colonial rule`], ans:1, exp:`Apartheid was official government policy in South Africa from 1948 to the early 1990s, systematically segregating and disadvantaging non-white citizens; it ended following negotiations and Nelson Mandela's election as president in 1994.` },
      { q:`Ghana, led by Kwame Nkrumah, holds the distinction of being:`, ch:[`The last African country to gain independence`,`The only African country never colonized`,`The first sub-Saharan African colony to achieve independence, in 1957`,`A former colony of Germany that remains a colony today`], ans:2, exp:`Ghana gained independence from British colonial rule in 1957 under the leadership of Kwame Nkrumah, becoming an inspiration for independence movements across the continent.` },
      { q:`Ethiopia is often noted in African history as one of the only African nations to:`, ch:[`Never develop its own written language`,`Be colonized exclusively by Portugal`,`Join the transatlantic slave trade as a major exporter`,`Successfully resist European colonization for most of the colonial era (aside from a brief Italian occupation from 1936-1941)`], ans:3, exp:`Ethiopia famously defeated an Italian invasion at the Battle of Adwa in 1896, preserving its independence through most of the colonial era, though Italy briefly occupied it from 1936 to 1941.` },
      { q:`The city of Timbuktu, located in the Songhai Empire, became renowned in the 15th and 16th centuries as a center of:`, ch:[`Islamic scholarship, learning, and manuscript production`,`Naval shipbuilding`,`European Christian missionary work`,`Industrial steel manufacturing`], ans:0, exp:`Timbuktu was home to prestigious Islamic universities and libraries, attracting scholars from across the Muslim world and producing thousands of manuscripts on subjects from law to astronomy.` }
    ]
  },
  {
    id:`ps146`, cat:`Behavioral & Social Sciences`, title:`Asian History Basics: Dynasties & Empires`, diff:`Easy`,
    qs:[
      { q:`The Qin Dynasty (221-206 BCE), under Emperor Qin Shi Huang, is historically significant because it:`, ch:[`Introduced Buddhism to China`,`Established the Silk Road`,`Ended imperial rule in China permanently`,`Unified China for the first time and standardized writing, currency, and measurements`], ans:3, exp:`Qin Shi Huang unified the warring Chinese states into a single empire and implemented standardized systems of writing, currency, and measurement; he is also known for beginning construction linked to the Great Wall and for the Terracotta Army built for his tomb.` },
      { q:`The Silk Road was a network of trade routes that connected:`, ch:[`China with the Mediterranean world, including the Middle East and Europe`,`Japan with Australia`,`India with the Americas`,`Only cities within China`], ans:0, exp:`The Silk Road facilitated the exchange of goods like silk, spices, and precious metals, as well as ideas, religions, and technologies, between East Asia and the Mediterranean world for centuries.` },
      { q:`Genghis Khan founded the Mongol Empire in the 13th century, which became known as:`, ch:[`The smallest empire in Asian history`,`The largest contiguous land empire in world history`,`A purely maritime trading empire`,`A short-lived empire that lasted only a few years`], ans:1, exp:`Under Genghis Khan and his successors, the Mongol Empire expanded to become the largest contiguous land empire in history, stretching from Eastern Europe to the Pacific Ocean.` },
      { q:`The Taj Mahal, one of the most famous buildings in the world, was built in India under the:`, ch:[`Ottoman Empire`,`Han Dynasty`,`Mughal Empire`,`Khmer Empire`], ans:2, exp:`The Taj Mahal was commissioned by Mughal emperor Shah Jahan in the 17th century as a mausoleum for his wife, Mumtaz Mahal, and remains one of the great architectural achievements of the Mughal Empire.` },
      { q:`The Han Dynasty (206 BCE-220 CE) is considered one of the most influential periods in Chinese history partly because:`, ch:[`It ended all trade with foreign countries`,`It introduced democracy to China`,`It was the shortest dynasty in Chinese history`,`It greatly expanded trade along the Silk Road and its cultural influence was so lasting that the majority ethnic group in China is still called "Han" today`], ans:3, exp:`The Han Dynasty expanded China's territory and trade networks, and its cultural and political influence was so significant that the largest ethnic group in China today identifies as "Han Chinese."` },
      { q:`The Meiji Restoration, beginning in 1868, transformed Japan by:`, ch:[`Rapidly modernizing its economy, military, and government along Western industrial lines`,`Isolating Japan completely from the rest of the world`,`Restoring feudal samurai rule permanently`,`Ending Japanese interest in technology`], ans:0, exp:`The Meiji Restoration ended Japan's feudal shogunate system and launched rapid modernization, including industrialization, a new constitution, and a modernized military, transforming Japan into a major world power within decades.` },
      { q:`The Ottoman Empire, one of the largest and longest-lasting empires in history, was centered in present-day:`, ch:[`Iran`,`Turkey`,`Saudi Arabia`,`Egypt`], ans:1, exp:`The Ottoman Empire, centered in present-day Turkey, controlled large territories across the Middle East, North Africa, and Southeastern Europe for over 600 years before collapsing after World War I.` },
      { q:`Angkor Wat, the largest religious monument in the world, was built by the Khmer Empire in present-day:`, ch:[`Vietnam`,`Thailand`,`Cambodia`,`Myanmar`], ans:2, exp:`Angkor Wat, originally built as a Hindu temple and later converted to Buddhist use, was constructed by the Khmer Empire in the 12th century in what is now Cambodia.` },
      { q:`The traditional caste system in India refers to a social hierarchy that historically:`, ch:[`Applied only to foreign visitors`,`Was based entirely on wealth alone`,`Changed completely every generation with no fixed categories`,`Divided society into hereditary groups that historically shaped occupation, social status, and marriage practices`], ans:3, exp:`The caste system is a traditional social hierarchy in India, historically dividing people into hereditary groups (castes) that influenced occupation, social interaction, and marriage; India's constitution today formally prohibits caste-based discrimination.` },
      { q:`Chinese emperors historically justified their rule using the concept known as the:`, ch:[`Mandate of Heaven, the belief that a just ruler had divine approval to govern, which could be lost through misrule`,`Divine Right of Kings, identical to European monarchies`,`Social Contract theory`,`Doctrine of Manifest Destiny`], ans:0, exp:`The Mandate of Heaven held that a ruler's authority came from divine approval, which could be forfeited if the ruler governed unjustly, historically used to explain and justify dynastic change in China.` },
      { q:`The Venetian traveler Marco Polo became famous for his account of his travels to:`, ch:[`The Aztec Empire`,`China, during the Mongol-ruled Yuan Dynasty`,`Sub-Saharan Africa`,`The Ottoman Empire only`], ans:1, exp:`Marco Polo traveled the Silk Road to China in the 13th century during the reign of Kublai Khan and later wrote a detailed account of his travels that introduced many Europeans to East Asian civilizations.` }
    ]
  },
  {
    id:`ps147`, cat:`Behavioral & Social Sciences`, title:`The United Nations & International Relations Basics`, diff:`Easy`,
    qs:[
      { q:`The United Nations was founded in 1945, primarily to:`, ch:[`Promote international peace, security, and cooperation among nations after the devastation of World War II`,`Replace all national governments with a single world government`,`Serve exclusively as a military alliance`,`Regulate international currency exchange rates`], ans:0, exp:`The UN was established after World War II by 51 founding member states to prevent future wars, promote international cooperation, and provide a forum for resolving disputes between nations.` },
      { q:`The UN Security Council has five permanent members with veto power over substantive resolutions. Which of the following is one of them?`, ch:[`Germany`,`The United States`,`Brazil`,`India`], ans:1, exp:`The five permanent Security Council members are the United States, United Kingdom, France, Russia, and China; each can veto substantive resolutions.` },
      { q:`In the UN General Assembly, each member state has:`, ch:[`Votes proportional to its population`,`No voting rights at all`,`One equal vote, regardless of size or wealth`,`Votes proportional to its military spending`], ans:2, exp:`Unlike the Security Council, where five members hold veto power, the General Assembly operates on a "one country, one vote" principle, giving every member state equal voting weight.` },
      { q:`NATO (North Atlantic Treaty Organization) is fundamentally a:`, ch:[`Global trade organization`,`Human rights court`,`United Nations agency for refugees`,`Military alliance in which member states pledge mutual defense if one is attacked`], ans:3, exp:`NATO, founded in 1949, is a collective defense alliance in which an attack on one member is treated as an attack on all, under Article 5 of its founding treaty.` },
      { q:`In international relations, "diplomacy" refers to:`, ch:[`The practice of managing relations and negotiating between countries, typically through dialogue rather than force`,`The use of military force to settle disputes`,`Economic sanctions imposed unilaterally`,`A country's internal legal system`], ans:0, exp:`Diplomacy is the practice of conducting negotiations and maintaining relationships between countries through dialogue, representatives, and formal agreements rather than through force.` },
      { q:`The concept of national "sovereignty" in international relations refers to a state's:`, ch:[`Obligation to follow orders from other countries`,`Supreme authority to govern itself within its own borders, free from outside interference`,`Requirement to join international organizations`,`Duty to share its natural resources with neighboring states`], ans:1, exp:`Sovereignty is the principle that a state has ultimate authority over its own territory and internal affairs, a foundational concept in the modern international system.` },
      { q:`The World Health Organization (WHO), a specialized agency of the United Nations, is primarily focused on:`, ch:[`International trade disputes`,`Global military coordination`,`Coordinating international public health efforts and responding to global health threats`,`Managing global currency exchange`], ans:2, exp:`The WHO coordinates international responses to health emergencies, sets global health guidelines, and works to improve public health outcomes worldwide.` },
      { q:`Economic sanctions, a common tool of international relations, refer to:`, ch:[`Formal declarations of war`,`Foreign aid packages with no conditions attached`,`Military occupations of another country`,`Restrictions on trade or financial transactions imposed to pressure a country to change its policies`], ans:3, exp:`Sanctions are non-military measures, such as trade restrictions or asset freezes, used by countries or international bodies to pressure a target nation to change specific behaviors or policies.` },
      { q:`UN peacekeeping missions typically involve:`, ch:[`Troops from various member states deployed, often with the host country's consent, to help maintain ceasefires and support stability after conflicts`,`The UN's own permanent standing army invading conflict zones`,`Only economic aid with no personnel involved`,`Automatic military intervention in any country's internal politics`], ans:0, exp:`UN peacekeeping forces are typically made up of troops voluntarily contributed by member states and are deployed, often with the consent of the parties involved, to help maintain ceasefires and support post-conflict stability.` },
      { q:`When multiple countries work together and coordinate policy on an issue, this approach is called:`, ch:[`Isolationism`,`Multilateralism`,`Unilateralism`,`Protectionism`], ans:1, exp:`Multilateralism refers to countries coordinating their policies and actions together, often through international organizations, as opposed to unilateralism, where a single country acts alone.` },
      { q:`The League of Nations, formed after World War I as a precursor to the United Nations, is generally considered to have:`, ch:[`Successfully prevented World War II`,`Included the United States as a founding and active member`,`Ultimately failed to prevent the outbreak of World War II and lacked enforcement power`,`Still exists today under a different name`], ans:2, exp:`The League of Nations, established in 1920, lacked enforcement mechanisms and key member participation (notably, the U.S. never joined), and it ultimately failed to prevent the aggression that led to World War II; it was replaced by the United Nations in 1945.` }
    ]
  },
  {
    id:`ps148`, cat:`Behavioral & Social Sciences`, title:`Human Rights: Origins & Key Documents`, diff:`Medium`,
    qs:[
      { q:`The Universal Declaration of Human Rights (UDHR), a foundational international human rights document, was adopted by the United Nations in:`, ch:[`1919`,`1948`,`1965`,`1989`], ans:1, exp:`The UDHR was adopted by the UN General Assembly in 1948, outlining fundamental rights and freedoms to which all human beings are entitled, though it is a declaration rather than a legally binding treaty.` },
      { q:`The Magna Carta, signed in England in 1215, is historically significant because it:`, ch:[`Established the first democracy in Europe`,`Abolished the English monarchy`,`Was one of the first documents to limit the power of a monarch and establish that even rulers were subject to law`,`Created the United Nations`], ans:2, exp:`The Magna Carta forced King John of England to accept limits on his power, establishing the important precedent that even a monarch was bound by law, influencing later constitutional and human rights documents.` },
      { q:`The Declaration of the Rights of Man and of the Citizen, a foundational document proclaiming liberty, equality, and property as natural rights, emerged from:`, ch:[`The American Civil War`,`The English Civil War`,`The Russian Revolution`,`The French Revolution`], ans:3, exp:`Adopted in 1789 during the French Revolution, the Declaration of the Rights of Man and of the Citizen proclaimed that all men are born free and equal in rights, influencing human rights thinking worldwide.` },
      { q:`In human rights theory, a "negative right" (such as freedom from torture) generally requires:`, ch:[`That the government refrain from certain actions against individuals`,`That the government actively provide a specific service, like healthcare`,`No legal recognition at all`,`Approval from a foreign government`], ans:0, exp:`Negative rights obligate governments to refrain from interfering with individual freedoms (e.g., freedom of speech, freedom from torture), while positive rights require the government to actively provide something, like education or healthcare.` },
      { q:`The Geneva Conventions are a set of international treaties primarily focused on:`, ch:[`Regulating global trade tariffs`,`Establishing humanitarian standards for the treatment of wounded soldiers, prisoners of war, and civilians during armed conflict`,`Setting rules for international sporting events`,`Governing internet privacy laws`], ans:1, exp:`The Geneva Conventions establish international legal standards for humane treatment during war, including protections for wounded soldiers, prisoners of war, and civilians.` },
      { q:`Under international law, "genocide" is legally defined as acts committed with the intent to:`, ch:[`Overthrow a foreign government`,`Restrict immigration`,`Destroy, in whole or in part, a national, ethnic, racial, or religious group`,`Enforce economic sanctions`], ans:2, exp:`The 1948 Genocide Convention defines genocide as specific acts (such as killing or causing serious harm) committed with the intent to destroy a national, ethnic, racial, or religious group, in whole or in part.` },
      { q:`The Nuremberg Trials, held after World War II, were significant in the development of human rights law because they:`, ch:[`Established the League of Nations`,`Ended the Cold War`,`Created the modern Olympics`,`Established the precedent that individuals, including government and military leaders, could be held internationally accountable for war crimes and crimes against humanity`], ans:3, exp:`The Nuremberg Trials prosecuted Nazi leaders for war crimes and crimes against humanity, setting an important precedent that individuals, not just states, could be held legally responsible for atrocities under international law.` },
      { q:`Organizations like Amnesty International and Human Rights Watch are examples of:`, ch:[`Non-governmental organizations (NGOs) that monitor and advocate for human rights around the world`,`Official agencies of the United Nations`,`Branches of the U.S. government`,`International military alliances`], ans:0, exp:`Amnesty International and Human Rights Watch are independent non-governmental organizations that research, document, and advocate against human rights abuses worldwide.` },
      { q:`The Convention on the Rights of the Child is an international treaty focused specifically on protecting the rights of:`, ch:[`Refugees`,`Children`,`Persons with disabilities`,`Indigenous peoples`], ans:1, exp:`Adopted in 1989, the Convention on the Rights of the Child sets out civil, political, economic, social, and cultural rights specifically for children and is one of the most widely ratified human rights treaties in history.` },
      { q:`Rights such as freedom of speech, freedom of religion, and freedom of the press are commonly grouped under the broader category of:`, ch:[`Economic rights`,`Property rights`,`Civil liberties`,`Trade rights`], ans:2, exp:`Civil liberties are basic individual freedoms, such as speech, religion, and press, that are protected from government interference and form a core part of many human rights frameworks.` },
      { q:`The International Criminal Court (ICC), established in 2002, has jurisdiction to prosecute individuals for:`, ch:[`Minor traffic violations across borders`,`Corporate tax evasion`,`Civil contract disputes between countries`,`Serious international crimes such as genocide, war crimes, and crimes against humanity`], ans:3, exp:`The ICC is a permanent international tribunal established to prosecute individuals (not states) for the most serious crimes of international concern, including genocide, war crimes, and crimes against humanity.` }
    ]
  },
  {
    id:`ps149`, cat:`Behavioral & Social Sciences`, title:`Positive Psychology: Grit, Resilience & Growth Mindset`, diff:`Easy`,
    qs:[
      { q:`Positive psychology, a field pioneered by psychologist Martin Seligman, focuses primarily on:`, ch:[`Diagnosing mental illness`,`Treating trauma exclusively through medication`,`Studying human strengths, well-being, and what allows people and communities to flourish`,`Analyzing brain structures using imaging technology`], ans:2, exp:`Positive psychology, largely founded by Martin Seligman in the late 1990s, shifted psychological research toward studying strengths, happiness, and flourishing, complementing the field's traditional focus on mental illness.` },
      { q:`Psychologist Angela Duckworth defined "grit" as:`, ch:[`Natural talent alone`,`The ability to avoid all failure`,`A fixed personality trait present from birth`,`Passion and sustained perseverance toward long-term goals, even in the face of setbacks`], ans:3, exp:`Duckworth's research suggests that grit, the combination of passion and persistent effort over time, is a strong predictor of achievement, sometimes even more so than raw talent alone.` },
      { q:`According to psychologist Carol Dweck, a "growth mindset" is the belief that:`, ch:[`Abilities and intelligence can be developed through effort, learning, and persistence`,`Intelligence is fixed at birth and cannot change`,`Only naturally talented people can succeed`,`Failure should always be avoided at all costs`], ans:0, exp:`Dweck's research distinguishes a "growth mindset" (believing abilities can improve with effort) from a "fixed mindset" (believing abilities are static), showing that growth mindsets are linked to greater resilience and achievement.` },
      { q:`In psychology, "resilience" refers to a person's ability to:`, ch:[`Avoid stress entirely by eliminating challenges`,`Adapt well and recover effectively in the face of adversity, trauma, or significant stress`,`Suppress all negative emotions permanently`,`Rely exclusively on others to solve problems`], ans:1, exp:`Resilience describes the capacity to adapt and recover well when facing adversity, trauma, or significant sources of stress, rather than the complete avoidance of hardship.` },
      { q:`The concept of "learned helplessness," discovered by Martin Seligman in early research, describes:`, ch:[`A skill that must be taught in schools`,`A permanent, unchangeable personality trait`,`A state in which a person or animal, after repeated exposure to uncontrollable negative events, stops trying to change their situation even when change becomes possible`,`A form of physical exercise`], ans:2, exp:`Learned helplessness occurs when repeated exposure to uncontrollable negative events leads an organism to stop attempting to escape or improve its situation, even after conditions change and escape becomes possible; this research helped Seligman later develop positive psychology.` },
      { q:`A person with a "fixed mindset," as described by Carol Dweck, tends to believe that:`, ch:[`Skills always improve dramatically with practice`,`Setbacks are valuable opportunities to learn`,`Effort is the most important factor in success`,`Their intelligence and talents are unchangeable traits, which can lead them to avoid challenges for fear of failure`], ans:3, exp:`People with a fixed mindset believe their abilities are static, which can make them avoid challenges or give up easily, since failure feels like proof of a permanent limitation rather than a chance to grow.` },
      { q:`Positive psychologists have developed classifications of "character strengths" (such as curiosity, kindness, and perseverance) partly to:`, ch:[`Help people identify and build on their personal strengths rather than focusing only on weaknesses`,`Replace all psychiatric diagnoses`,`Rank people by intelligence alone`,`Eliminate the need for effort in achieving goals`], ans:0, exp:`Classifications like the VIA (Values in Action) character strengths framework encourage focusing on and cultivating personal strengths, complementing traditional approaches that focus mainly on deficits or disorders.` },
      { q:`Research on "explanatory style" suggests that optimistic people tend to interpret setbacks as:`, ch:[`Permanent and affecting every area of their life`,`Temporary and specific to the situation, rather than a permanent reflection of their overall worth`,`Proof that they should give up entirely`,`Someone else's fault in every case`], ans:1, exp:`People with an optimistic explanatory style tend to view negative events as temporary and limited to a specific situation, whereas a pessimistic style attributes setbacks to permanent, pervasive causes.` },
      { q:`Psychologist Mihaly Csikszentmihalyi described "flow" as a mental state characterized by:`, ch:[`Constant distraction and multitasking`,`Boredom during routine tasks`,`Complete absorption and full engagement in an activity, often when a challenge closely matches one's skill level`,`Avoidance of all challenging tasks`], ans:2, exp:`Flow is a state of deep, focused engagement in an activity, often experienced when a task's difficulty is well matched to a person's skill level, resulting in high enjoyment and performance.` },
      { q:`Research in positive psychology has found that regularly practicing gratitude (such as keeping a gratitude journal) is associated with:`, ch:[`Decreased life satisfaction`,`No measurable psychological effects`,`Increased feelings of isolation`,`Improved mood, well-being, and life satisfaction`], ans:3, exp:`Multiple studies have found that intentionally practicing gratitude, such as regularly writing down things one is thankful for, is linked to improved mood, stronger relationships, and greater overall well-being.` },
      { q:`"Post-traumatic growth" refers to the phenomenon in which some individuals:`, ch:[`Experience positive psychological changes, such as greater personal strength or appreciation for life, as a result of struggling with highly challenging life circumstances`,`Are permanently unable to function after trauma`,`Forget traumatic events entirely`,`Avoid all future relationships after trauma`], ans:0, exp:`Post-traumatic growth describes positive psychological changes, such as increased personal strength, deeper relationships, or a greater appreciation for life, that some people experience as they work through the aftermath of highly challenging events.` }
    ]
  },
  {
    id:`ps150`, cat:`Behavioral & Social Sciences`, title:`Emotional Intelligence Basics`, diff:`Easy`,
    qs:[
      { q:`Emotional intelligence (EI) is generally defined as the ability to:`, ch:[`Suppress all emotional expression`,`Score highly on standardized IQ tests`,`Avoid emotionally difficult situations entirely`,`Perceive, understand, manage, and use emotions effectively in oneself and others`], ans:3, exp:`Emotional intelligence refers to the capacity to recognize, understand, regulate, and appropriately use emotions, both one's own and those of others, in order to navigate social situations effectively.` },
      { q:`The concept of emotional intelligence was significantly popularized for a general audience by psychologist:`, ch:[`Daniel Goleman`,`Sigmund Freud`,`B.F. Skinner`,`Jean Piaget`], ans:0, exp:`Daniel Goleman's 1995 book "Emotional Intelligence" brought the concept to widespread public attention, arguing that EI can be as important as traditional IQ for success in life and work.` },
      { q:`"Self-awareness," a core component of emotional intelligence, refers to the ability to:`, ch:[`Predict other people's future behavior perfectly`,`Recognize and understand one's own emotions as they occur`,`Avoid ever feeling negative emotions`,`Memorize facts quickly`], ans:1, exp:`Self-awareness involves accurately recognizing and understanding one's own emotions, moods, and how they affect thoughts and behavior, forming a foundation for the other components of emotional intelligence.` },
      { q:`"Empathy," another core component of emotional intelligence, refers to the ability to:`, ch:[`Control other people's emotions directly`,`Remain emotionally detached from others at all times`,`Understand and share the feelings and perspectives of another person`,`Only recognize emotions in oneself, not others`], ans:2, exp:`Empathy is the capacity to understand and share another person's feelings or perspective, an important skill for building relationships and navigating social interactions.` },
      { q:`"Self-regulation," a key component of emotional intelligence, involves the ability to:`, ch:[`Never experience strong emotions`,`Let emotions dictate behavior without any thought`,`Ignore emotions entirely and act purely on logic`,`Manage and control one's emotional responses in a healthy, appropriate way`], ans:3, exp:`Self-regulation refers to the ability to manage disruptive emotions and impulses, allowing a person to respond thoughtfully to situations rather than reacting impulsively.` },
      { q:`"Social skills," as a component of emotional intelligence, involve a person's ability to:`, ch:[`Build and manage relationships effectively, including communicating clearly and resolving conflicts`,`Avoid all social interaction`,`Control others' opinions through manipulation`,`Perform well on written exams`], ans:0, exp:`Social skills within the emotional intelligence framework refer to the ability to build rapport, communicate effectively, and manage relationships and conflicts in a constructive way.` },
      { q:`"Motivation," as one of Goleman's components of emotional intelligence, refers to an internal drive to:`, ch:[`Work only when directly rewarded with money`,`Pursue goals with energy and persistence, often for reasons beyond external rewards like money or status`,`Avoid setting any personal goals`,`Compare oneself constantly to others`], ans:1, exp:`In Goleman's model, motivation refers to a passion for pursuing goals with energy and persistence, often driven by internal factors such as personal growth rather than purely external rewards.` },
      { q:`Unlike some traditional views of intelligence (IQ) as relatively fixed, most researchers agree that emotional intelligence:`, ch:[`Is entirely genetic and cannot change`,`Decreases naturally as people age`,`Can generally be developed and improved over time through practice and self-reflection`,`Has no impact on relationships or workplace success`], ans:2, exp:`Most research suggests emotional intelligence skills, such as self-awareness and empathy, can be strengthened over time through intentional practice, feedback, and reflection, unlike the more fixed view often applied to traditional IQ.` },
      { q:`Research has generally found that high emotional intelligence is associated with:`, ch:[`Worse teamwork and communication`,`No difference in leadership effectiveness`,`Increased social isolation`,`Stronger relationships, better teamwork, and more effective leadership`], ans:3, exp:`Studies have linked higher emotional intelligence to improved communication, stronger interpersonal relationships, better conflict resolution, and more effective leadership in workplace and social settings.` },
      { q:`The skill of accurately identifying and labeling specific emotions (e.g., distinguishing "frustrated" from "anxious" rather than just saying "bad") is sometimes called:`, ch:[`Emotional granularity`,`Emotional amnesia`,`Cognitive dissonance`,`Selective attention`], ans:0, exp:`Emotional granularity refers to the ability to identify and label emotions with precision and nuance; research suggests people with higher emotional granularity tend to regulate their emotions more effectively.` },
      { q:`A key distinction between emotional intelligence (EI) and traditional IQ is that IQ primarily measures:`, ch:[`Empathy and relationship-building skills`,`Cognitive and analytical reasoning abilities, while EI focuses more on emotional and social skills`,`How well someone manages their emotions`,`A person's ability to recognize emotions in others`], ans:1, exp:`Traditional IQ tests primarily assess cognitive and analytical reasoning abilities, such as logic and problem-solving, whereas emotional intelligence focuses on the perception, understanding, and management of emotions in social contexts.` }
    ]
  },
  {
    id:`ps151`, cat:`Behavioral & Social Sciences`, title:`Group Polarization & Decision-Making in Teams`, diff:`Medium`,
    qs:[
      { q:`"Group polarization" refers to the tendency for group discussion to:`, ch:[`Strengthen and intensify the average initial leaning or opinion of group members, pushing the group to a more extreme position`,`Always produce a perfectly moderate compromise`,`Eliminate all disagreement within the group`,`Have no measurable effect on individual opinions`], ans:0, exp:`Group polarization occurs when discussing an issue with like-minded others tends to make the group's shared opinion more extreme than the average individual opinion members held beforehand.` },
      { q:`"Groupthink," a term coined by psychologist Irving Janis, describes a phenomenon in which:`, ch:[`Groups always make better decisions than individuals`,`A group's desire for harmony and conformity leads members to suppress dissenting views, resulting in poor or irrational decision-making`,`Group members are randomly assigned tasks`,`Individuals refuse to work in groups at all`], ans:1, exp:`Groupthink occurs when a cohesive group's desire for consensus and harmony overrides critical evaluation of alternatives, often leading to flawed decisions because dissenting opinions are suppressed or self-censored.` },
      { q:`The "risky shift" phenomenon, an early example of group polarization research, found that groups discussing a decision involving risk often:`, ch:[`Always chose the safest possible option`,`Made identical decisions to any single individual`,`Ended up favoring riskier decisions than the average individual member initially preferred`,`Refused to make any decision at all`], ans:2, exp:`Early research on the "risky shift" found that group discussion could push decisions toward greater risk-taking than individuals would choose alone, an effect later understood as one form of group polarization (the opposite, a "cautious shift," can also occur depending on initial leanings).` },
      { q:`Assigning someone the role of "devil's advocate" in a group discussion is a strategy specifically designed to:`, ch:[`Speed up decision-making by skipping debate`,`Ensure everyone agrees quickly`,`Reward the most senior group member`,`Deliberately challenge the group's emerging consensus and encourage critical evaluation of alternatives, helping to reduce groupthink`], ans:3, exp:`A devil's advocate is intentionally assigned to argue against the prevailing group opinion, which helps surface overlooked risks or weaknesses and counteracts the pressure toward premature consensus seen in groupthink.` },
      { q:`"Social loafing" refers to the tendency for individuals to:`, ch:[`Exert less individual effort when working in a group than when working alone`,`Work harder in groups than alone`,`Refuse to participate in any group activity`,`Always take on leadership roles in groups`], ans:0, exp:`Social loafing describes the tendency for people to put in less individual effort on a task when working as part of a group, especially when individual contributions are not easily identified.` },
      { q:`Research on team decision-making generally suggests that including members with diverse perspectives and backgrounds tends to:`, ch:[`Always slow decisions with no benefit`,`Improve the quality of group decisions by expanding the range of information and viewpoints considered`,`Guarantee unanimous agreement`,`Eliminate the need for a group leader`], ans:1, exp:`Diverse teams tend to consider a wider range of information and perspectives, which can improve decision quality and help counteract the narrowing effects of groupthink, though it can also require more effective facilitation to manage disagreement productively.` },
      { q:`Traditional group brainstorming, despite its popularity, has been found by some research to sometimes be less productive than individuals generating ideas separately, partly due to a phenomenon called:`, ch:[`Groupthink`,`Social loafing only`,`"Production blocking," where only one person can speak at a time, limiting idea generation`,`The risky shift`], ans:2, exp:`Production blocking occurs because in a group, only one person can talk at a time, which can interrupt other members' trains of thought and reduce the overall number of ideas generated compared to individuals brainstorming separately and then combining results.` },
      { q:`"Consensus decision-making" in a team differs from simple majority-rule voting because consensus generally requires:`, ch:[`A single leader to make the final call alone`,`A random lottery to decide`,`Only 51% of members to agree`,`General agreement from all or nearly all group members before finalizing a decision`], ans:3, exp:`Consensus decision-making seeks broad agreement or acceptance from all group members, which can take longer than majority-rule voting but may result in stronger buy-in and commitment to the final decision.` },
      { q:`Online "echo chambers," where people mostly encounter opinions similar to their own, are considered a modern real-world example of:`, ch:[`Group polarization, since repeated exposure to similar views can push opinions toward more extreme positions`,`Social loafing`,`Production blocking`,`The risky shift only`], ans:0, exp:`Echo chambers can amplify group polarization because when people primarily interact with others who share similar views, repeated affirmation can push their opinions toward more extreme versions of the original view.` },
      { q:`According to Janis's research, groupthink is most likely to occur in groups that are:`, ch:[`Composed of strangers with no shared history`,`Highly cohesive, insulated from outside opinions, and under pressure to reach a quick decision`,`Extremely diverse in background and opinion`,`Led by a leader who actively encourages dissent`], ans:1, exp:`Janis identified that groupthink is more likely in highly cohesive groups that are isolated from outside perspectives, face time pressure, and have a directive leader who signals a preferred outcome, all of which discourage critical examination of alternatives.` },
      { q:`To reduce the risks of groupthink and group polarization, experts commonly recommend that team leaders:`, ch:[`Discourage any outside input`,`Make all final decisions without consulting the team`,`Actively seek out dissenting opinions and encourage open, critical discussion before finalizing a decision`,`Limit the group to members who already agree`], ans:2, exp:`Encouraging open debate, actively soliciting dissenting views, and avoiding premature closure on a decision are common strategies recommended to counteract groupthink and reduce the risk of group polarization.` }
    ]
  },
  {
    id:`ps152`, cat:`Behavioral & Social Sciences`, title:`Nature vs Nurture: The Basics of the Debate`, diff:`Easy`,
    qs:[
      { q:`The "nature vs. nurture" debate in psychology concerns the relative contributions of:`, ch:[`Diet and exercise to physical health`,`Genetics (nature) and environmental experiences (nurture) to human development and behavior`,`Religion and government to society`,`Climate and geography to culture`], ans:1, exp:`The nature vs. nurture debate examines how much of human development, behavior, and traits are shaped by inherited genetics ("nature") versus environmental and experiential factors ("nurture").` },
      { q:`Psychologists commonly use "twin studies," comparing identical and fraternal twins, to help estimate:`, ch:[`How much twins resemble each other physically`,`The average lifespan of twins`,`How much a trait is influenced by genetics versus environment`,`Which twin was born first`], ans:2, exp:`Because identical twins share nearly 100% of their genes while fraternal twins share about 50%, comparing similarities between the two types of twins helps researchers estimate the relative genetic and environmental contributions to a trait.` },
      { q:`The term "heritability," when used in behavioral genetics, refers to:`, ch:[`The exact percentage of an individual trait that is inherited`,`A trait that is entirely determined by upbringing`,`A guarantee that a trait will be passed to all offspring`,`A statistical estimate of how much variation in a trait across a population can be attributed to genetic differences, within that specific population and environment`], ans:3, exp:`Heritability is a population-level statistic estimating the proportion of trait variation attributable to genetic differences among individuals in a specific environment; it does not describe how much of an individual's trait is due to genes versus environment.` },
      { q:`The modern scientific consensus on the nature vs. nurture debate generally holds that most human traits and behaviors result from:`, ch:[`A complex interaction between genetic and environmental factors, rather than either factor alone`,`Genetics alone, with environment playing no role`,`Environment alone, with genetics playing no role`,`Random chance unrelated to either genetics or environment`], ans:0, exp:`Most contemporary researchers reject a strict either/or framing, instead emphasizing that genes and environment interact continuously to shape development, behavior, and traits (sometimes called "nature via nurture").` },
      { q:`The field of "epigenetics" studies how:`, ch:[`New genetic mutations are randomly created`,`Environmental factors can influence which genes are turned on or off (expressed) without changing the underlying DNA sequence`,`Twins develop identical personalities`,`IQ scores are calculated`], ans:1, exp:`Epigenetics examines how environmental factors, such as stress, diet, or toxins, can affect gene expression (turning genes "on" or "off") without altering the DNA sequence itself, providing a mechanism for environment to influence biology.` },
      { q:`"Adoption studies" help researchers study nature vs. nurture by comparing adopted children's traits to those of:`, ch:[`Their adoptive siblings only`,`Random unrelated strangers`,`Both their biological parents (genetic influence) and their adoptive parents (environmental influence)`,`Their adoptive parents exclusively`], ans:2, exp:`Because adopted children share genes with their biological parents but environment with their adoptive parents, comparing similarities to each group helps researchers disentangle genetic from environmental influences.` },
      { q:`Philosopher John Locke's concept of "tabula rasa" (blank slate) proposed that:`, ch:[`Human personality is fixed entirely by genetics at birth`,`Twins always have identical personalities`,`Only wealthy individuals can develop intelligence`,`The mind is essentially blank at birth and is shaped primarily by experience and environment`], ans:3, exp:`Locke's "tabula rasa" concept argued that people are born without built-in mental content and that knowledge and character come primarily from experience, representing a historically influential "nurture-heavy" view later modified by modern behavioral genetics research.` },
      { q:`Historically, some extreme "nature-only" viewpoints claimed that traits like intelligence were almost entirely fixed by heredity; modern research has shown this view to be:`, ch:[`An oversimplification, since environment and gene-environment interactions play a substantial and well-documented role in shaping most traits`,`Completely accurate with no need for revision`,`Irrelevant, since genetics play no role in any trait`,`Proven true only for physical traits, never for behavior`], ans:0, exp:`Modern behavioral genetics research has shown that strict "nature-only" claims oversimplify development; both genes and environment, along with their interaction, substantially shape most psychological and behavioral traits.` },
      { q:`The genetic condition phenylketonuria (PKU) is often cited as a classic example of gene-environment interaction because:`, ch:[`It has no connection to environment at all`,`Its harmful effects on intellectual development can largely be prevented through a controlled diet (an environmental intervention), despite it being caused by a genetic mutation`,`It can only be treated with surgery`,`It is caused entirely by environmental toxins, not genetics`], ans:1, exp:`PKU is a genetic disorder that impairs the body's ability to process a particular amino acid, but its most severe effects, including intellectual disability, can largely be prevented through a controlled low-phenylalanine diet, illustrating how environmental intervention can offset a genetic predisposition.` },
      { q:`Studies of identical twins who were separated at birth and raised in different environments are particularly valuable to researchers because they help isolate:`, ch:[`The effects of birth order`,`The effects of diet alone`,`The influence of shared genetics apart from a shared environment`,`The effects of religious upbringing only`], ans:2, exp:`Because separated identical twins share nearly all their genes but grew up in different environments, similarities between them can offer insight into genetic influences that are less confounded by a shared upbringing.` },
      { q:`The concept of "reaction range" in behavioral genetics suggests that genes typically:`, ch:[`Determine a trait with complete precision, leaving no room for environmental influence`,`Have no influence on the range of possible outcomes for a trait`,`Only matter for physical traits, not behavioral ones`,`Set a range of possible outcomes for a trait, while environmental factors help determine where within that range an individual actually ends up`], ans:3, exp:`The reaction range concept suggests that genetics establishes boundaries for a trait's possible expression (such as potential height range), while environmental factors, like nutrition, influence where within that range an individual's actual trait falls.` }
    ]
  },
  {
    id:`ps153`, cat:`Behavioral & Social Sciences`, title:`Attachment Theory Basics`, diff:`Easy`,
    qs:[
      { q:`Attachment theory, originally developed by psychologist John Bowlby, focuses on:`, ch:[`How children learn language`,`How adolescents develop identity`,`The emotional bond that forms between an infant and their primary caregiver, and its influence on later development`,`How memory changes with age`], ans:2, exp:`Bowlby's attachment theory proposes that the early emotional bond between an infant and their primary caregiver serves important survival functions and shapes the child's expectations about relationships later in life.` },
      { q:`Psychologist Mary Ainsworth developed a research procedure called the "Strange Situation" to:`, ch:[`Measure a child's IQ`,`Test children's memory recall`,`Study sleep patterns in infants`,`Observe and classify infants' attachment styles based on their reactions to separation from and reunion with a caregiver`], ans:3, exp:`In the Strange Situation, researchers observe how infants react when briefly separated from and then reunited with their caregiver in an unfamiliar setting, allowing classification into different attachment styles.` },
      { q:`Infants classified with a "secure attachment" style typically:`, ch:[`Show some distress when the caregiver leaves but are easily comforted and seek contact upon their return`,`Show no reaction at all to the caregiver leaving or returning`,`Avoid the caregiver entirely upon their return`,`Show extreme, inconsolable distress that continues even after the caregiver returns`], ans:0, exp:`Securely attached infants use their caregiver as a "secure base" for exploration, show some distress upon separation, but are readily comforted and seek closeness when the caregiver returns.` },
      { q:`Infants classified with an "avoidant attachment" style typically:`, ch:[`Cling excessively to the caregiver at all times`,`Show little distress when the caregiver leaves and tend to avoid or ignore the caregiver upon their return`,`Cannot be separated from the caregiver at all`,`Show attachment only to strangers`], ans:1, exp:`Avoidantly attached infants tend to show minimal distress when separated from their caregiver and often avoid or ignore the caregiver when they return, sometimes linked to caregivers who are consistently unresponsive to the infant's needs.` },
      { q:`Infants classified with a "resistant" (or "ambivalent") attachment style typically:`, ch:[`Show no distress when separated from their caregiver`,`Are easily and quickly comforted upon reunion`,`Become very distressed when the caregiver leaves but resist being comforted, sometimes seeking and rejecting contact simultaneously upon reunion`,`Attach equally to any adult in the room`], ans:2, exp:`Resistant (ambivalent) attachment is marked by intense distress at separation combined with difficulty being soothed upon reunion, sometimes showing contradictory behavior like seeking then resisting comfort.` },
      { q:`A "disorganized" attachment style, the fourth category identified in later attachment research, is characterized by:`, ch:[`Perfectly consistent, calm behavior in all situations`,`Complete indifference to the caregiver`,`Strong and exclusive preference for strangers over the caregiver`,`Inconsistent, sometimes contradictory or fearful behavior toward the caregiver, often associated with frightening or unpredictable caregiving`], ans:3, exp:`Disorganized attachment involves a lack of a clear, consistent strategy for dealing with the caregiver, sometimes including freezing, fear, or contradictory approach-avoidance behaviors, and has been linked to inconsistent or frightening caregiving experiences.` },
      { q:`According to attachment theory, the "internal working model" refers to:`, ch:[`A mental framework, formed from early attachment experiences, that shapes a person's expectations and behavior in future relationships`,`A child's physical growth chart`,`A formal school curriculum for social skills`,`A caregiver's daily schedule`], ans:0, exp:`The internal working model is a set of expectations about relationships, formed through early attachment experiences, that a person tends to carry forward, influencing how they approach relationships later in life.` },
      { q:`Harry Harlow's classic experiments with infant rhesus monkeys and surrogate "wire" and "cloth" mothers demonstrated that:`, ch:[`Infants attach only to whichever surrogate provides food`,`Infants preferred a soft, comforting surrogate over a wire surrogate that provided food, suggesting comfort and contact matter more than food alone in attachment`,`Monkeys form no attachment bonds at all`,`Attachment forms only after several years of life`], ans:1, exp:`Harlow found that infant monkeys spent far more time clinging to a soft cloth surrogate mother than to a wire surrogate that dispensed food, showing that comfort and contact, not just nourishment, are central to attachment formation.` },
      { q:`Attachment researchers often describe the first months to first couple of years of life as a "sensitive period" because:`, ch:[`Attachment cannot form at any other point in life`,`Infants have no emotional responses during this time`,`This is generally when attachment bonds most readily form, and disruptions during this period can have lasting effects on development`,`This is when children first learn to read`], ans:2, exp:`The early years are considered a sensitive period for attachment because this is when bonds with caregivers most readily develop, and significant disruptions or neglect during this window can have lasting effects on social and emotional development.` },
      { q:`Modern research on attachment suggests that a person's infant attachment style:`, ch:[`Perfectly and permanently determines every future relationship with no possibility of change`,`Has no connection whatsoever to later relationships`,`Only applies to relationships with parents, never romantic partners`,`Can influence, but does not rigidly determine, later relationship patterns, since attachment styles can shift with new experiences`], ans:3, exp:`While early attachment patterns are associated with tendencies in later relationships, researchers emphasize that attachment style is not fixed for life; new relationships and experiences can shift a person's patterns over time.` },
      { q:`A key practical implication of attachment research is that consistently responsive caregiving (promptly and warmly responding to an infant's needs) tends to be associated with:`, ch:[`A greater likelihood of secure attachment`,`No difference in attachment outcomes`,`A greater likelihood of avoidant attachment`,`Delayed physical growth`], ans:0, exp:`Research consistently links caregivers who respond sensitively and consistently to an infant's needs with a higher likelihood that the infant will develop a secure attachment style.` }
    ]
  },
  {
    id:`ps154`, cat:`Behavioral & Social Sciences`, title:`The Bystander Effect & Helping Behavior`, diff:`Easy`,
    qs:[
      { q:`The "bystander effect" refers to the phenomenon in which individuals are:`, ch:[`More likely to help a victim as the number of witnesses increases`,`Equally likely to help regardless of how many other people are present`,`Only willing to help family members`,`Less likely to help a person in need when other bystanders are present, compared to when they are alone`], ans:3, exp:`The bystander effect describes how the presence of other people can reduce an individual's likelihood of helping someone in need, an effect researchers began studying intensively after the widely publicized 1964 murder of Kitty Genovese.` },
      { q:`One major explanation for the bystander effect, called "diffusion of responsibility," suggests that:`, ch:[`As the number of bystanders increases, each individual feels less personal responsibility to act, assuming someone else will help`,`People feel more personally responsible when more witnesses are present`,`Responsibility is always assigned to the first person on the scene`,`Diffusion of responsibility only occurs among close friends`], ans:0, exp:`Diffusion of responsibility suggests that when multiple bystanders are present, each individual feels less personally responsible for helping, since the responsibility feels "shared" or spread among the group.` },
      { q:`"Pluralistic ignorance" contributes to the bystander effect when bystanders:`, ch:[`Refuse to look at each other at all`,`Look to the reactions of other bystanders for cues, and mistakenly conclude that since no one else looks alarmed, the situation must not be a real emergency`,`Always immediately call for help`,`Are unaware that other people are present`], ans:1, exp:`Pluralistic ignorance occurs when bystanders look to others' calm reactions for social cues about how to interpret an ambiguous situation, mistakenly concluding it isn't an emergency because no one else appears alarmed, when in fact everyone may be feeling similarly uncertain.` },
      { q:`The 1964 murder of Kitty Genovese in New York City became widely associated with the bystander effect because early news reports claimed that:`, ch:[`No witnesses were present at all`,`The attacker was immediately apprehended by witnesses`,`Numerous witnesses failed to intervene or call for help, which (though later shown to be somewhat exaggerated) helped inspire foundational research on the bystander effect by psychologists Bibb Latane and John Darley`,`The victim was a police officer`], ans:2, exp:`Initial reporting on the Genovese case claimed many witnesses did nothing to help, a narrative later shown to be exaggerated in some respects, but the case nonetheless helped spur Latane and Darley's foundational experimental research on the bystander effect.` },
      { q:`"Evaluation apprehension" can contribute to the bystander effect when a person hesitates to help because they:`, ch:[`Do not notice the emergency at all`,`Believe help is not needed`,`Have no ability to physically assist`,`Fear being judged or embarrassed by other bystanders if they intervene incorrectly or unnecessarily`], ans:3, exp:`Evaluation apprehension refers to a bystander's fear of being negatively judged by others for intervening, which can make people hesitant to act even when they recognize a situation may require help.` },
      { q:`Research on helping behavior has found that people are generally more likely to intervene in an emergency when:`, ch:[`Fewer other bystanders are present, or when they have specific skills or training relevant to the emergency`,`As many other people as possible are present`,`They are complete strangers to everyone else involved`,`The emergency takes place in a large crowd`], ans:0, exp:`Studies show bystanders are generally more likely to help when fewer other people are present (reducing diffusion of responsibility) and when they have specific training, such as first aid, that gives them confidence to act.` },
      { q:`According to the decision model of helping developed by Latane and Darley, before a bystander helps, they must go through several steps, including noticing the event, interpreting it as an emergency, and:`, ch:[`Waiting for police to arrive before doing anything else`,`Taking personal responsibility to act and deciding how to help`,`Consulting a lawyer`,`Recording the event on video first`], ans:1, exp:`Latane and Darley's model describes helping as a sequence of decisions: noticing the event, interpreting it as an emergency, assuming personal responsibility, deciding how to help, and then actually implementing that help; a "no" at any step can prevent intervention.` },
      { q:`"Prosocial behavior" is a broad psychological term referring to:`, ch:[`Any behavior that benefits only the person performing it`,`Behavior aimed at avoiding all social contact`,`Voluntary behavior intended to benefit other people, such as helping, sharing, or comforting`,`Behavior that violates social norms`], ans:2, exp:`Prosocial behavior is voluntary behavior carried out with the intention of benefiting others, encompassing acts like helping, sharing, cooperating, and comforting.` },
      { q:`"Altruism" specifically refers to helping behavior that is:`, ch:[`Always required by law`,`Performed only in exchange for a reward`,`Motivated entirely by fear of punishment`,`Motivated primarily by genuine concern for another person's welfare, sometimes even at a cost to oneself`], ans:3, exp:`Altruism describes helping behavior motivated by a genuine concern for someone else's well-being, sometimes at a personal cost, distinguishing it from helping done mainly for external reward or reciprocity.` },
      { q:`Bystander intervention training programs, now common on many college campuses, are designed to:`, ch:[`Teach people to recognize potential emergencies and provide specific steps for safely intervening or seeking help`,`Discourage any form of intervention`,`Punish people who fail to intervene`,`Eliminate the need for campus security`], ans:0, exp:`Bystander intervention training teaches people to recognize warning signs of an emergency (such as harassment or dangerous drinking) and gives them concrete strategies for intervening safely or getting help, aiming to counteract the bystander effect.` },
      { q:`Studies on helping behavior have found that people are often more likely to help someone when they perceive that person as:`, ch:[`A complete stranger from a very different background`,`Similar to themselves in some meaningful way, such as sharing a group identity`,`In no distress whatsoever`,`Located far away from the bystander`], ans:1, exp:`Research suggests people are often more willing to help those they perceive as similar to themselves or as members of a shared in-group, illustrating how social identity can influence helping behavior.` }
    ]
  },
  {
    id:`ps155`, cat:`Behavioral & Social Sciences`, title:`Implicit Bias & Stereotyping Basics`, diff:`Medium`,
    qs:[
      { q:`"Implicit bias" refers to:`, ch:[`Unconscious attitudes or stereotypes that can affect a person's understanding, actions, and decisions without their conscious awareness`,`Attitudes a person openly and consciously admits to holding`,`A formal legal term with no psychological basis`,`Bias that occurs only in written documents`], ans:0, exp:`Implicit biases are attitudes or stereotypes that operate outside a person's conscious awareness or control, yet can still influence judgments and behavior, even in people who consciously reject prejudice.` },
      { q:`The key difference between "explicit bias" and "implicit bias" is that explicit bias involves:`, ch:[`Attitudes a person is entirely unaware of`,`Attitudes and beliefs a person consciously holds and is often willing to openly state`,`Bias that can never be measured`,`Bias that only affects behavior in laboratory settings`], ans:1, exp:`Explicit bias refers to attitudes a person consciously holds and can typically report, while implicit bias operates below conscious awareness, meaning a person may hold implicit biases that conflict with their explicitly stated beliefs.` },
      { q:`The Implicit Association Test (IAT), widely used in psychological research, measures implicit bias by:`, ch:[`Asking direct survey questions about a person's beliefs`,`Analyzing a person's voting record`,`Measuring the speed and accuracy with which a person associates different concepts (such as social groups and positive or negative words) in a computer-based task`,`Conducting a structured job interview`], ans:2, exp:`The IAT measures implicit bias indirectly by timing how quickly and accurately participants pair different social categories with positive or negative words or images, with the assumption that faster associations reflect stronger automatic mental links.` },
      { q:`In social psychology, a "stereotype" is best defined as:`, ch:[`A behavior that is always intentionally harmful`,`A law that governs group behavior`,`A type of formal discrimination lawsuit`,`A generalized belief or assumption about the characteristics or traits of members of a particular group`], ans:3, exp:`A stereotype is a cognitive shortcut, a generalized belief about the traits or characteristics of members of a group, which can be inaccurate or overly simplistic when applied to any specific individual.` },
      { q:`Social scientists commonly distinguish "stereotype" (a belief), "prejudice" (an attitude or feeling), and "discrimination" as:`, ch:[`Unfair behavior or treatment directed at a person or group, often based on stereotypes or prejudice`,`Three words that mean exactly the same thing`,`Terms that apply only to racial issues`,`Concepts unrelated to each other`], ans:0, exp:`Stereotypes are cognitive beliefs about a group, prejudice is a negative (or positive) attitude or feeling toward a group, and discrimination is the behavioral act of treating individuals unfairly based on group membership; the three are related but conceptually distinct.` },
      { q:`"Stereotype threat," a concept studied by psychologists Claude Steele and Joshua Aronson, describes how:`, ch:[`Stereotypes have no effect on behavior or performance`,`Awareness of a negative stereotype about one's own group can create anxiety that actually impairs performance on a related task`,`Only positive stereotypes affect performance`,`Stereotype threat applies only to physical, not academic, performance`], ans:1, exp:`Stereotype threat research found that when people are aware of a negative stereotype about a group they belong to, the resulting anxiety can actually impair their performance on tasks related to that stereotype, even if they don't personally believe the stereotype.` },
      { q:`Research suggests that implicit biases can develop in a person even if they consciously reject prejudice, largely because these biases are shaped by:`, ch:[`Formal education alone`,`Direct personal experience only`,`Widespread cultural messages, media portrayals, and repeated associations absorbed over a lifetime, often without conscious awareness`,`Random chance with no identifiable cause`], ans:2, exp:`Implicit biases are thought to develop from repeated exposure to cultural stereotypes, media portrayals, and social patterns over a lifetime, which can shape automatic mental associations even in people who consciously and sincerely reject prejudice.` },
      { q:`Many organizations have implemented "implicit bias training" for employees; research on the effectiveness of typical one-time training sessions has generally found:`, ch:[`That such trainings eliminate implicit bias permanently and completely`,`No possible way to study their effects`,`That they always increase discriminatory behavior`,`Mixed results, with some studies showing short-term awareness gains but limited evidence of lasting changes in actual behavior from brief, one-time sessions`], ans:3, exp:`Research on brief, one-time implicit bias trainings has produced mixed results; some studies show short-term increases in awareness, but evidence for lasting changes in actual behavior is more limited, leading many researchers to recommend more sustained, structural interventions.` },
      { q:`"In-group bias" refers to the general human tendency to:`, ch:[`Favor and show preference toward members of one's own group over members of other groups`,`Treat all groups with perfect equal preference at all times`,`Favor only groups a person has never met`,`Avoid forming any group identity`], ans:0, exp:`In-group bias is the common tendency for people to favor members of groups they belong to (in-groups) over members of other groups (out-groups), which can occur even with minimal or arbitrary group distinctions.` },
      { q:`Studies examining real-world decision-making, such as resume screening or medical treatment recommendations, have found that implicit biases can:`, ch:[`Have absolutely no measurable effect on any real-world decisions`,`Subtly influence decisions like hiring or medical care, even when decision-makers do not intend or realize they are being influenced`,`Only affect decisions made by computers, not humans`,`Only be studied in laboratory settings, never in real institutions`], ans:1, exp:`Research using methods like identical resumes with different names has found that implicit biases can subtly shape real-world outcomes such as hiring decisions or medical treatment recommendations, even among people who do not intend to discriminate.` },
      { q:`Researchers studying ways to reduce the impact of implicit bias on decisions have found that using structured, standardized decision-making criteria (rather than open-ended judgment) tends to:`, ch:[`Have no effect on reducing bias`,`Always increase the influence of bias`,`Help reduce the influence of implicit bias by limiting reliance on subjective, unstructured judgment`,`Only work for financial decisions`], ans:2, exp:`Using structured, standardized criteria (such as clear rubrics for evaluating job candidates) tends to reduce opportunities for implicit bias to influence subjective judgment calls, compared to relying on open-ended, unstructured decision-making.` }
    ]
  },
  {
    id:`ps156`, cat:`Behavioral & Social Sciences`, title:`Work-Life Balance & Mental Health Basics for Students`, diff:`Easy`,
    qs:[
      { q:`"Work-life balance" generally refers to:`, ch:[`Spending exactly equal hours on school/work and leisure every single day`,`A state in which a person is able to reasonably manage the demands of school or work alongside personal life, relationships, and self-care`,`Avoiding all schoolwork or job responsibilities`,`A legal requirement in most workplaces`], ans:1, exp:`Work-life balance describes a sustainable state where a person can reasonably meet the demands of school or work while also maintaining time for personal well-being, relationships, and rest, rather than requiring a rigid equal split of hours.` },
      { q:`"Burnout" is best described as a state of:`, ch:[`Temporary tiredness that goes away after one night's sleep`,`Increased motivation caused by high achievement`,`Physical, emotional, and mental exhaustion caused by prolonged or chronic stress, often accompanied by reduced motivation and a sense of ineffectiveness`,`A medical condition unrelated to stress`], ans:2, exp:`Burnout is a state of chronic physical, emotional, and mental exhaustion resulting from prolonged stress, often marked by cynicism, reduced motivation, and a diminished sense of accomplishment; it is increasingly recognized among overworked students as well as employees.` },
      { q:`"Sleep hygiene" refers to a set of habits and practices, such as maintaining a consistent sleep schedule and limiting screen time before bed, that are designed to:`, ch:[`Guarantee a person never feels tired`,`Replace the need for sleep entirely`,`Only apply to people with diagnosed sleep disorders`,`Support consistent, good-quality sleep, which is closely linked to mental health, mood, and academic performance`], ans:3, exp:`Good sleep hygiene habits, such as consistent sleep and wake times and reducing screen exposure before bed, help support quality sleep, which research consistently links to better mood regulation, concentration, and academic performance.` },
      { q:`"Self-care" refers to:`, ch:[`Deliberate activities a person engages in to maintain or improve their own physical and mental well-being`,`A term used only in medical settings`,`Ignoring personal needs to focus entirely on achievement`,`An indulgent luxury with no real benefit`], ans:0, exp:`Self-care encompasses intentional actions, such as adequate sleep, exercise, social connection, and relaxation, that a person takes to support their physical and mental health, and is considered an important part of sustainable well-being, especially during demanding periods like school.` },
      { q:`Research on chronic, prolonged stress among students has found that it can negatively affect:`, ch:[`Only physical health, never mental or academic functioning`,`Concentration, memory, immune function, and increase the risk of anxiety and depression`,`Nothing measurable, since some stress is always beneficial`,`Only students who already have a diagnosed mental health condition`], ans:1, exp:`Chronic stress has been shown to impair concentration and memory, weaken immune function, and increase the risk of developing anxiety or depression, underscoring the importance of stress management for students.` },
      { q:`Psychologists distinguish "eustress" from "distress" by noting that eustress refers to:`, ch:[`Stress that is always harmful and should be eliminated`,`A term with no real scientific basis`,`A moderate, positive form of stress that can feel motivating and improve focus or performance`,`Stress experienced only by professional athletes`], ans:2, exp:`Eustress refers to a positive or motivating form of stress, such as the excitement before a challenging exam, that can enhance focus and performance, in contrast to distress, which is the harmful, overwhelming form of stress.` },
      { q:`Learning to set healthy "boundaries," such as designating specific times to stop studying or working each day, is a commonly recommended strategy for:`, ch:[`Eliminating the need for any schoolwork`,`Guaranteeing higher grades`,`Avoiding all social relationships`,`Protecting personal time and reducing the risk of burnout by preventing school or work demands from consuming all available time`], ans:3, exp:`Setting clear boundaries around when to stop working or studying helps protect time for rest, relationships, and other activities, which is widely recommended as a strategy for preventing burnout and maintaining overall well-being.` },
      { q:`Regular physical exercise has been consistently linked by research to:`, ch:[`Improved mood and reduced levels of stress and anxiety`,`No measurable effect on mental health`,`Worsened sleep quality in most people`,`Decreased academic performance`], ans:0, exp:`Numerous studies have found that regular physical exercise is associated with improved mood, reduced stress and anxiety, and better overall mental health, likely due in part to the release of mood-regulating brain chemicals.` },
      { q:`Having strong social support, such as supportive friends, family, or mentors, is considered by researchers to be:`, ch:[`Irrelevant to mental health outcomes`,`An important protective factor that can help buffer the negative effects of stress and support overall mental health`,`Only helpful for physical health, not mental health`,`A replacement for professional mental health treatment when needed`], ans:1, exp:`Strong social support networks are consistently associated with better mental health outcomes and can act as a buffer, helping people cope more effectively with stress and adversity.` },
      { q:`Research on procrastination has generally found that habitually delaying tasks tends to:`, ch:[`Reduce stress by giving a person more free time initially`,`Have no effect on stress levels`,`Increase stress overall, since it often creates greater time pressure and anxiety as deadlines approach`,`Only affect people who are naturally lazy`], ans:2, exp:`While procrastination may reduce stress briefly by avoiding an unpleasant task, research shows it tends to increase overall stress and anxiety as deadlines approach, and strategies like breaking tasks into smaller steps can help counteract the pattern.` },
      { q:`Mental health professionals generally emphasize that seeking help from a counselor or other mental health professional when struggling is:`, ch:[`A sign of personal weakness that should be avoided`,`Only appropriate for the most severe mental health crises`,`Something that should always be delayed as long as possible`,`A normal, proactive step that can help a person manage stress and mental health challenges before they become more severe`], ans:3, exp:`Mental health professionals consistently emphasize that seeking help, such as talking to a school counselor, is a proactive and healthy response to struggling with stress or mental health challenges, not a sign of weakness, and can help address issues before they escalate.` }
    ]
  }
];
